// server/upload.js
// Multer configuration for product image uploads.
//
// Security notes (classroom demo, but still done properly):
//  - Filenames are generated by the server (UUID + extension), never from
//    user input, so path traversal is impossible.
//  - The client-provided MIME type is NOT trusted. We sniff the file's magic
//    bytes and only accept JPEG, PNG and WebP.
//  - Only images are allowed anywhere in the app, so uploaded files can never
//    be executed as scripts by the web server.
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const multer = require('multer');

// Overridable so the automated tests can point uploads at a throwaway
// folder instead of the developer's real uploads directory.
const UPLOAD_DIR = process.env.UPLOAD_DIR
  ? path.resolve(process.env.UPLOAD_DIR)
  : path.join(__dirname, '..', 'uploads');
// 5 MB = 5,000,000 bytes (decimal MB, as advertised in the UI).
const MAX_IMAGE_BYTES = Number(process.env.MAX_IMAGE_BYTES) || 5 * 1000 * 1000;

// Make sure the uploads folder exists on start-up.
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

/** Detect the real image type from the first bytes of the buffer. */
function sniffImageType(buffer) {
  if (!buffer || buffer.length < 12) return null;

  // JPEG: FF D8 FF
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return { extension: '.jpg', mime: 'image/jpeg' };
  }
  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47 &&
    buffer[4] === 0x0d &&
    buffer[5] === 0x0a &&
    buffer[6] === 0x1a &&
    buffer[7] === 0x0a
  ) {
    return { extension: '.png', mime: 'image/png' };
  }
  // WebP: "RIFF" .... "WEBP"
  if (
    buffer.toString('ascii', 0, 4) === 'RIFF' &&
    buffer.toString('ascii', 8, 12) === 'WEBP'
  ) {
    return { extension: '.webp', mime: 'image/webp' };
  }
  return null;
}

/** Remove an already-written file (used when validation fails). */
function removeFile(file) {
  if (file && file.path && fs.existsSync(file.path)) {
    fs.unlinkSync(file.path);
  }
}

const storage = multer.diskStorage({
  destination(request, file, callback) {
    callback(null, UPLOAD_DIR);
  },
  filename(request, file, callback) {
    // Random, collision-proof name; extension is decided later in the filter
    // once we know the real file type, so we write it here from the MIME and
    // then overwrite `filename` in the fileFilter below via `file.filename`.
    const extension = path.extname(file.originalname || '').toLowerCase();
    const safeExtension = ['.jpg', '.jpeg', '.png', '.webp'].includes(extension)
      ? extension
      : '.bin';
    callback(null, `${crypto.randomUUID()}${safeExtension}`);
  },
});

const upload = multer({
  storage,
  limits: {
    fileSize: MAX_IMAGE_BYTES,
    files: 1,
    fields: 10,
  },
  fileFilter(request, file, callback) {
    // Read a small chunk of the file to sniff its magic bytes.
    // Multer's diskStorage writes the whole file, so we validate after write
    // instead: here we only do a cheap early rejection for obviously huge or
    // missing files. Real type checking happens in `validateUploadedImage`.
    if (!file) {
      return callback(new Error('No file received.'));
    }
    callback(null, true);
  },
});

/**
 * Validate an uploaded file's real content after it has been written to disk.
 * @returns {{ ok: true, value: { path: string, url: string, mime: string } } | { ok: false, error: string }}
 */
function validateUploadedImage(file) {
  if (!file) {
    return { ok: false, error: 'No image file was received.' };
  }

  // Read the first 16 bytes to sniff the format.
  let header;
  try {
    const fd = fs.openSync(file.path, 'r');
    header = Buffer.alloc(16);
    fs.readSync(fd, header, 0, 16, 0);
    fs.closeSync(fd);
  } catch (error) {
    removeFile(file);
    return { ok: false, error: 'Uploaded file could not be read.' };
  }

  const detected = sniffImageType(header);
  if (!detected) {
    removeFile(file);
    return {
      ok: false,
      error: 'Unsupported file type. Please upload a JPEG, PNG or WebP image.',
    };
  }

  // Normalise the stored filename to the detected type and store only a
  // relative URL in the product record.
  const finalName = `${path.parse(file.filename).name}${detected.extension}`;
  const finalPath = path.join(UPLOAD_DIR, finalName);
  if (file.path !== finalPath) {
    try {
      if (fs.existsSync(file.path)) fs.renameSync(file.path, finalPath);
    } catch (error) {
      removeFile(file);
      return { ok: false, error: 'Could not finalise the uploaded image.' };
    }
  }

  return {
    ok: true,
    value: {
      path: finalPath,
      url: `/uploads/${finalName}`,
      mime: detected.mime,
    },
  };
}

/** Delete an image file from disk, ignoring missing files. */
function deleteImageFile(relativeUrl) {
  if (!relativeUrl || !relativeUrl.startsWith('/uploads/')) return;
  // Only allow simple filenames - blocks any attempt at path traversal.
  const fileName = relativeUrl.slice('/uploads/'.length);
  if (!fileName || fileName.includes('/') || fileName.includes('\\') || fileName.includes('..')) {
    return;
  }
  const fullPath = path.join(UPLOAD_DIR, fileName);
  if (fs.existsSync(fullPath)) {
    try {
      fs.unlinkSync(fullPath);
    } catch (error) {
      console.warn('[upload] could not delete', fileName);
    }
  }
}

module.exports = {
  upload,
  validateUploadedImage,
  deleteImageFile,
  discardUploadedFile: removeFile,
  MAX_IMAGE_BYTES,
  UPLOAD_DIR,
};
